};

'use client';

import { useEffect, useRef } from 'react';
import { useChatStore, type ChatMessage } from '../stores/chatStore';

function bubbleColor(msg: ChatMessage): { bg: string; label: string } {
  if (msg.role === 'user') return { bg: '#1e3a5f', label: '你' };
  if (msg.role === 'system') return { bg: '#3a1414', label: '系统' };
  if (msg.eventType === 'tool_use') return { bg: '#2a2333', label: msg.toolName ?? '工具' };
  return { bg: '#1e2a1f', label: 'Agent' };
}

export function MessageStream() {
  const messages = useChatStore((s) => s.messages);
  const isStreaming = useChatStore((s) => s.isStreaming);
  const endRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    endRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isStreaming]);

  return (
    <div style={styles.wrap}>
      {messages.length === 0 && (
        <div style={styles.empty}>输入消息开始对话。Agent 能直接改写本项目源码。</div>
      )}
      {messages.map((msg) => {
        const { bg, label } = bubbleColor(msg);
        return (
          <div key={msg.id} style={{ ...styles.bubble, background: bg }}>
            <div style={styles.meta}>
              <strong>{label}</strong>
              <span style={styles.time}>{new Date(msg.timestamp).toLocaleTimeString()}</span>
            </div>
            {msg.eventType === 'tool_use' ? (
              <pre style={styles.pre}>{msg.content}</pre>
            ) : (
              <div style={styles.content}>{msg.content}</div>
            )}
          </div>
        );
      })}
      {isStreaming && <div style={styles.thinking}>Agent 思考中…</div>}
      <div ref={endRef} />
    </div>
  );
}

const styles: Record<string, React.CSSProperties> = {
  wrap: { flex: 1, overflowY: 'auto', padding: 16, display: 'flex', flexDirection: 'column', gap: 10 },
  empty: { color: '#666', textAlign: 'center', marginTop: 40 },
  bubble: { borderRadius: 8, padding: '10px 14px', maxWidth: '85%' },
  meta: { display: 'flex', justifyContent: 'space-between', fontSize: 11, opacity: 0.6, marginBottom: 4 },
  time: { fontSize: 10 },
  content: { whiteSpace: 'pre-wrap', wordBreak: 'break-word', lineHeight: 1.5, fontSize: 14 },
  pre: { margin: 0, fontSize: 12, whiteSpace: 'pre-wrap', wordBreak: 'break-word', color: '#b9c5d6' },
  thinking: { color: '#888', fontStyle: 'italic', fontSize: 13, padding: '0 4px' },
};

'use client';

import { useState, type KeyboardEvent } from 'react';
import { useSendMessage } from '../hooks/useSendMessage';

export function ChatInput() {
  const { handleSend, sending } = useSendMessage();
  const [text, setText] = useState('');

  const submit = async (): Promise<void> => {
    if (!text.trim()) return;
    await handleSend(text);
    setText('');
  };

  const onKeyDown = (e: KeyboardEvent<HTMLTextAreaElement>): void => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      void submit();
    }
  };

  return (
    <div style={styles.bar}>
      <textarea
        value={text}
        onChange={(e) => setText(e.target.value)}
        onKeyDown={onKeyDown}
        placeholder='给 Agent 发消息…（如：把输入框改宽一点）'
        rows={4}
        style={styles.input}
        disabled={sending}
      />
      <button onClick={() => void submit()} disabled={sending || !text.trim()} style={styles.btn}>
        发送
      </button>
    </div>
  );
}

const styles: Record<string, React.CSSProperties> = {
  bar: { display: 'flex', gap: 8, padding: 12, borderTop: '1px solid #2a2d33' },
  input: {
    flex: 1,
    resize: 'none',
    background: '#1a1d23',
    color: '#e6e6e6',
    border: '1px solid #2a2d33',
    borderRadius: 6,
    padding: '10px 12px',
    fontSize: 16,
    outline: 'none',
  },
  btn: {
    background: '#3b82f6',
    color: '#fff',
    border: 'none',
    borderRadius: 6,
    padding: '0 20px',
    fontSize: 14,
    fontWeight: 600,
  },
};

