/** TOML 字符串转义：-c 的 value 部分按 TOML 解析，需引号+转义 */
function toTomlString(value: string): string {
  const escaped = value.replace(/[\\"]/g, '\\$&').replace(/\n/g, '\\n').replace(/\r/g, '\\r').replace(/\t/g, '\\t');
  return `"${escaped}"`;
}

