    ];
    if (this.compiledL0) {
      configArgs.push('-c', `developer_instructions=${toTomlString(this.compiledL0)}`);
    }

    let args: string[];
    if (sessionId) {
      // resume：用 -c sandbox_mode（resume 子命令不接受 --sandbox flag）
      args = [
        'exec',
        'resume',
        sessionId,
        '--json',
        '--skip-git-repo-check',
        '-c',
        `sandbox_mode=${toTomlString(sandboxMode)}`,
        ...configArgs,
        ...(model ? ['-m', model] : []),
        ...this.descriptor.cli.extraArgs,
        '--',
        '-',
      ];
    } else {
      args = [
        'exec',
        '--json',
        '--sandbox',
        sandboxMode,
        '--skip-git-repo-check',
        ...configArgs,
        ...(model ? ['-m', model] : []),
        ...this.descriptor.cli.extraArgs,
        '--',
        '-',
      ];
    }

    const spawnOpts: CliSpawnOptions = {
      command: this.descriptor.cli.command,
      args,
      cwd,
      stdinInput: prompt,
      env: { CODEX_HOME: codexHome },
      ...(options?.signal ? { signal: options.signal } : {}),
      ...(options?.invocationId ? { invocationId: options.invocationId } : {}),
    };

    let sawSubstantiveOutput = false;
    let terminalYielded = false;

    try {
      for await (const event of spawnCli(spawnOpts)) {
        if (isCliTimeout(event)) {
          terminalYielded = true;
          yield {
            type: 'error',
            nodeId: this.nodeId,
            error: `Codex CLI 响应超时 (${Math.round(event.timeoutMs / 1000)}s)`,
            metadata,
            timestamp: Date.now(),
          };
          yield { type: 'done', nodeId: this.nodeId, metadata, timestamp: Date.now() };
          return;
        }
        if (isCliError(event)) {
          // codex 0.98+ 成功后也 exit 1；有实质输出则抑制
          if (event.exitCode === 1 && event.signal === null && sawSubstantiveOutput) {
            continue;
          }
          terminalYielded = true;
          yield {
            type: 'error',
            nodeId: this.nodeId,
            error: `${KILL_GRACE_NOTICE} (code: ${event.exitCode ?? 'null'})`,
            metadata,
            timestamp: Date.now(),
          };
          yield { type: 'done', nodeId: this.nodeId, metadata, timestamp: Date.now() };
          return;
        }

        // 跟踪实质输出（item.completed 产生 text/tool 结果）
        if (typeof event === 'object' && event !== null) {
          const e = event as Record<string, unknown>;
          if (e.type === 'item.completed') sawSubstantiveOutput = true;
        }

        const messages = transformCodexEvent(event, this.nodeId);
        for (const msg of messages) {
          if (msg.type === 'done' || msg.type === 'error') terminalYielded = true;
          yield msg;
        }
      }
      // 流正常结束但没收到 turn.completed → 兜底补一个 done
      if (!terminalYielded) {
        yield { type: 'done', nodeId: this.nodeId, metadata, timestamp: Date.now() };
      }
    } catch (err) {
      yield {
        type: 'error',
        nodeId: this.nodeId,
        error: `Codex 调用失败: ${(err as Error).message}`,
        metadata,
        timestamp: Date.now(),
      };
      yield { type: 'done', nodeId: this.nodeId, metadata, timestamp: Date.now() };
    }
  }
}

/**
 * per-node 会话链
 * 存/取每个节点的当前活跃 sessionId，供 CLI --resume 续上下文。
 * 借鉴 clowder-ai SessionChainStore（精简：每节点一个 active.json）。
 */
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { getProjectRoot } from '../utils/project-root.js';
import type { NodeDescriptor } from './NodeDescriptor.js';
import { resolveDescriptorPaths } from './NodeDescriptor.js';

interface ActiveSession {
  sessionId: string;
  updatedAt: number;
}

function sessionsDir(descriptor: NodeDescriptor): string {
  const resolved = resolveDescriptorPaths(descriptor);
  const dir = resolved.memory?.session?.dir ?? join('agents', descriptor.id, 'sessions');
  return resolve(getProjectRoot(), dir);
}

/** 读取节点当前活跃 sessionId（用于 resume） */
export function getActiveSession(descriptor: NodeDescriptor): string | undefined {
  if (descriptor.memory?.session?.resume === false) return undefined;
  const dir = sessionsDir(descriptor);
  const file = join(dir, 'active.json');
  if (!existsSync(file)) return undefined;
  try {
    const data: unknown = JSON.parse(readFileSync(file, 'utf-8'));
    if (
      typeof data === 'object' &&
      data !== null &&
      typeof (data as ActiveSession).sessionId === 'string'
    ) {
      return (data as ActiveSession).sessionId;
    }
  } catch {
    // 损坏的 active.json 忽略，下次会重新建会话
  }
  return undefined;
}

/** 记录节点新会话的 sessionId（来自 CLI session_init 事件） */
export function setActiveSession(descriptor: NodeDescriptor, sessionId: string): void {
  if (descriptor.memory?.session?.resume === false) return;
  const dir = sessionsDir(descriptor);
  if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
  const file = join(dir, 'active.json');
  const data: ActiveSession = { sessionId, updatedAt: Date.now() };
  writeFileSync(file, JSON.stringify(data, null, 2) + '\n', 'utf-8');
}

/** 清除节点活跃会话（重置） */
export function clearActiveSession(descriptor: NodeDescriptor): void {
  const dir = sessionsDir(descriptor);
  const file = join(dir, 'active.json');
  if (existsSync(file)) writeFileSync(file, '{}\n', 'utf-8');
}

'use client';

import { useEffect, useRef, useState } from 'react';
import { io, type Socket } from 'socket.io-client';
import { useChatStore, type AgentEvent } from '../stores/chatStore';

const API_URL = process.env.NEXT_PUBLIC_API_URL ?? 'http://localhost:3004';

export function useSocket(): { connected: boolean } {
  const socketRef = useRef<Socket | null>(null);
  const activeNodeId = useChatStore((s) => s.activeNodeId);
  const pushAgentEvent = useChatStore((s) => s.pushAgentEvent);
  const [connected, setConnected] = useState(false);

  useEffect(() => {
    const socket = io(API_URL, { transports: ['websocket', 'polling'] });
    socketRef.current = socket;

    socket.on('connect', () => {
      setConnected(true);
      socket.emit('join_node', activeNodeId);
    });
    socket.on('disconnect', () => setConnected(false));
    socket.on('agent_message', (msg: AgentEvent) => {
      pushAgentEvent(msg);
    });

    return () => {
      socket.disconnect();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // 切换节点时重新 join
  useEffect(() => {
    const socket = socketRef.current;
    if (socket && socket.connected) {
      socket.emit('join_node', activeNodeId);
    }
  }, [activeNodeId]);

  return { connected };
}

